def shipping_fee(total, region, fragile):
    if total < 0 or region not in {'north', 'central', 'south'}: raise ValueError('input')
    fee = {'north': 300, 'central': 200, 'south': 400}[region]
    if total >= 5000: fee = max(0, fee - 150)
    if fragile: fee += 250
    return fee

def retention_days(kind, encrypted, legal_hold):
    if kind not in {'logs', 'backups', 'exports'}: raise ValueError('kind')
    if legal_hold: return 365
    days = {'logs': 30, 'backups': 90, 'exports': 7}[kind]
    if encrypted and kind != 'exports': days += 15
    return days

def retry_budget(priority, attempts, outage):
    if priority not in {'low', 'normal', 'high'} or type(attempts) is not int or attempts < 0: raise ValueError('input')
    limit = {'low': 2, 'normal': 4, 'high': 6}[priority] + (2 if outage else 0)
    return max(0, limit - attempts)

